const { skins } = require("./skins.js");

class charInfo {
    constructor(name, alias, anime, anialias, gender, image, id, rarity) {
        this._name = name;
        this._alias = alias;
        this._anime = anime;
        this._anialias = anialias;
        this._gender = gender;
        this._image = image;
        this._id = id;
        this._rarity = rarity;
    };
    get name() {
        return this._name;
    };
    get alias() {
        return this._alias;
    };
    get anime() {
        return this._anime;
    };
    get anialias() {
        return this._anialias;
    };
    get gender() {
        return this._gender;
    };
    get image() {
        return this._image;
    };
    get id() {
        return this._id;
    };
    get rarity() {
        return this._rarity;
    };
    get rarityValue() {
        return { "D": 0, "C": 1, "B": 2, "A": 3, "S": 4, "SS": 5, "EX": 6 }[this._rarity];
    };

    getImage(premium, url, skin = undefined) {
        if (premium > 2 && url) return url;
        if (skin === undefined) return this.image;
        return skins[skin].image;
    };
};

