module.exports.characters = characters;
module.exports.auniq = [...new Set(characters.map((e) => e.anime))];
module.exports.uniqueAnimeCharacters = characters.reduce((acc, char) => {
    if (!acc.seenAnimes[char.anime]) {
        acc.seenAnimes[char.anime] = true;
        acc.result.push(char);
    };
    return acc;
}, { seenAnimes: {}, result: [] }).result.sort((a, b) => a.anime.localeCompare(b.anime));

const charactersF = characters.filter((e) => e.gender === "F");
module.exports.charactersF = charactersF;
const charactersM = characters.filter((e) => e.gender === "M");
module.exports.charactersM = charactersM;
const charactersSS = characters.filter((e) => e.rarity === "SS");
module.exports.charactersSS = charactersSS;
const charactersS = characters.filter((e) => e.rarity === "S");
module.exports.charactersS = charactersS;
const charactersA = characters.filter((e) => e.rarity === "A");
module.exports.charactersA = charactersA;
const charactersB = characters.filter((e) => e.rarity === "B");
module.exports.charactersB = charactersB;
const charactersC = characters.filter((e) => e.rarity === "C");
module.exports.charactersC = charactersC;
const charactersD = characters.filter((e) => e.rarity === "D");
module.exports.charactersD = charactersD;


// DEBUGGING CONTROLS
// DEBUGGING CONTROLS
// DEBUGGING CONTROLS

// Warn if ',' in name (would mess with some commands because , is being used to separate strings)
characters.forEach((e) => {
    if (e.name.includes(",") || e.alias.some((a) => a.includes(","))) console.log("WARNING! Character with symbol ',' in name or alias: " + e.name);
});

// Check if duplicate names
{
    // let names = characters.map((e) => e.name).sort();
    let names = characters.reduce((acc, char) => acc.concat(char.name, char.alias), []).sort();
    let len = names.length - 1, res = "";
    while (len--) if (names[len - 1] === names[len]) res += names[len--] + "\n";
    if (res) console.log("WARNING! Duplicate names: " + res);
}

// Check gender, rarity and ID
characters.forEach((e, i) => {
    if (!["M", "F"].includes(e.gender)) console.log("WARNING! Missing gender " + e.gender + ": " + e.name);
    if (!["EX", "SS", "S", "A", "B", "C", "D"].includes(e.rarity)) console.log("WARNING! Missing rarity " + e.rarity + ": " + e.name);
    if (e.id !== i) console.log("WARNING! Wrong ID " + e.id + " in: " + e.name);
});

// Check if duplicate links
{
    let links = characters.map((e) => e.image).sort();
    let len = links.length - 1, res = "";
    while (len--) if (links[len - 1] === links[len]) res += links[len--] + "\n";
    if (res) console.log("WARNING! Duplicate links: " + res);
}